BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;SET LOCAL search_path=pg_catalog;
DO $installed$ DECLARE r record;d text;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='folha_privado.horario_ad13_valido(jsonb,boolean)'::regprocedure AND proowner='postgres'::regrole AND prosecdef=false AND provolatile='i' AND proconfig=ARRAY['search_path=pg_catalog'] AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='66f19facb23dc111f39aeb8e395d5bd75eb70eb016f1efe2043083800afffbd4') THEN RAISE EXCEPTION 'AD03_FUNCTION_DRIFT: folha_privado.horario_ad13_valido(jsonb,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='folha_privado.diaria_ad14_valida(public.folha_avaliacoes_diarias,boolean)'::regprocedure AND proowner='postgres'::regrole AND prosecdef=false AND provolatile='i' AND proconfig=ARRAY['search_path=pg_catalog'] AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='8b2e36eb831f61ed9b4bb106c65a0851bd8f6ab894214a83d93cac2ccbfbe630') THEN RAISE EXCEPTION 'AD03_FUNCTION_DRIFT: folha_privado.diaria_ad14_valida(public.folha_avaliacoes_diarias,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='folha_privado.diaria_recalcular(uuid,date,uuid)'::regprocedure AND proowner='postgres'::regrole AND prosecdef=true AND provolatile='v' AND proconfig=ARRAY['search_path=pg_catalog'] AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='5ad0846b9140478670e861d330a30e9a8903a1e047df44ff9a0e48d860f97f49') THEN RAISE EXCEPTION 'AD03_FUNCTION_DRIFT: folha_privado.diaria_recalcular(uuid,date,uuid)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public.fn_folha_diaria_gestao_v2(text,jsonb,boolean,text)'::regprocedure AND proowner='postgres'::regrole AND prosecdef=true AND provolatile='v' AND proconfig=ARRAY['search_path=pg_catalog'] AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='6ffbdf8c54d4f2ab6d77b087813d9c343fd6bcf280b9cd1bce50fad4aee7497d') THEN RAISE EXCEPTION 'AD03_FUNCTION_DRIFT: public.fn_folha_diaria_gestao_v2(text,jsonb,boolean,text)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='folha_privado.jornada_ad03_semana_valida(jsonb)'::regprocedure AND proowner='postgres'::regrole AND prosecdef=false AND provolatile='i' AND proconfig=ARRAY['search_path=pg_catalog'] AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='67b8a42c0bcb4aca44559e8812ee7301a75800444f2c173d255baee52df5fb7d') THEN RAISE EXCEPTION 'AD03_FUNCTION_DRIFT: folha_privado.jornada_ad03_semana_valida(jsonb)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='folha_privado.jornada_ad03_modelo(text)'::regprocedure AND proowner='postgres'::regrole AND prosecdef=false AND provolatile='i' AND proconfig=ARRAY['search_path=pg_catalog'] AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='1e30c771d45bc18e4abd5fcfb0006cf70914a5ece9e2bc2ac209bc14178e61e4') THEN RAISE EXCEPTION 'AD03_FUNCTION_DRIFT: folha_privado.jornada_ad03_modelo(text)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='folha_privado.jornada_ad03_guardar()'::regprocedure AND proowner='postgres'::regrole AND prosecdef=false AND provolatile='v' AND proconfig=ARRAY['search_path=pg_catalog'] AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='33b40adb5774d2b57ce38e870dc9d8b8d92bd543f1f1c8b87f1e53fa9388b6e0') THEN RAISE EXCEPTION 'AD03_FUNCTION_DRIFT: folha_privado.jornada_ad03_guardar()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='folha_privado.jornada_ad03_avaliacao_valida(public.folha_avaliacoes_diarias)'::regprocedure AND proowner='postgres'::regrole AND prosecdef=true AND provolatile='s' AND proconfig=ARRAY['search_path=pg_catalog'] AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='dc305d706255331923c55d4bbd270739e85c675deae388a275a41781d4c89a02') THEN RAISE EXCEPTION 'AD03_FUNCTION_DRIFT: folha_privado.jornada_ad03_avaliacao_valida(public.folha_avaliacoes_diarias)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='folha_privado.diaria_referencia(uuid,date)'::regprocedure AND proowner='postgres'::regrole AND prosecdef=true AND provolatile='v' AND proconfig=ARRAY['search_path=pg_catalog'] AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='c084917189e4fae57677c0cff9213b28b179ab2a987bedf453f6e2a7d9b42a8e') THEN RAISE EXCEPTION 'AD03_FUNCTION_DRIFT: folha_privado.diaria_referencia(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public.fn_folha_jornadas_v2(text,jsonb,boolean,text)'::regprocedure AND proowner='postgres'::regrole AND prosecdef=true AND provolatile='v' AND proconfig=ARRAY['search_path=pg_catalog'] AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='a87d101f79786050f21d183f70c48f7f04ea71747e1430b47f2be16d258adc6f') THEN RAISE EXCEPTION 'AD03_FUNCTION_DRIFT: public.fn_folha_jornadas_v2(text,jsonb,boolean,text)';END IF;

IF (SELECT count(*) FROM pg_constraint WHERE conrelid='public.folha_avaliacoes_diarias'::regclass)<>43 THEN RAISE EXCEPTION 'AD03_CONSTRAINT_COUNT_DRIFT';END IF;
FOR r IN SELECT * FROM primeline_ad03_backup.constraints LOOP
 d:=replace(r.definicao,'expected_minutes >= 1','expected_minutes >= 0');d:=replace(d,'''administrativo''::text]', '''administrativo''::text, ''individual''::text]');d:=replace(d,'''schedule_retro_correct''::text]', '''schedule_retro_correct''::text, ''jornada_assign''::text]');
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=r.tabela::regclass AND conname=r.conname AND convalidated AND pg_get_constraintdef(oid)=d) THEN RAISE EXCEPTION 'AD03_CONSTRAINT_DRIFT: %',r.conname;END IF;
END LOOP;
IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='public.folha_jornadas_individuais_versoes'::regclass AND relrowsecurity AND relowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM aclexplode((SELECT relacl FROM pg_class WHERE oid='public.folha_jornadas_individuais_versoes'::regclass)) x WHERE x.grantee<>'postgres'::regrole) THEN RAISE EXCEPTION 'AD03_TABLE_ACL_DRIFT';END IF;
IF EXISTS(SELECT 1 FROM public.folha_jornadas_individuais_versoes WHERE folha_privado.jornada_ad03_semana_valida(semana) IS NOT TRUE) OR EXISTS(SELECT 1 FROM public.folha_avaliacoes_diarias a WHERE folha_privado.diaria_ad14_valida(a,true) IS NOT TRUE OR folha_privado.jornada_ad03_avaliacao_valida(a) IS NOT TRUE) THEN RAISE EXCEPTION 'AD03_INVALID_REFERENCE';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='folha_jornada_ad03_guardar' AND tgrelid='public.folha_jornadas_individuais_versoes'::regclass AND tgenabled='O') OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.folha_avaliacoes_diarias'::regclass AND conname='folha_jornada_ad03_reference' AND convalidated) THEN RAISE EXCEPTION 'AD03_SCHEMA_DRIFT';END IF;
IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x WHERE n.nspname='folha_privado' AND p.proname LIKE 'jornada_ad03_%' AND x.grantee<>p.proowner) THEN RAISE EXCEPTION 'AD03_PRIVATE_HELPER_GRANT';END IF;
IF (SELECT array_agg(x::text ORDER BY x::text) FROM pg_proc p CROSS JOIN LATERAL unnest(p.proacl) x WHERE p.oid='public.fn_folha_jornadas_v2(text,jsonb,boolean,text)'::regprocedure) IS DISTINCT FROM ARRAY['authenticated=X/postgres','postgres=X/postgres'] THEN RAISE EXCEPTION 'AD03_RPC_GRANT';END IF;
END $installed$;
DO $data$ DECLARE r record;j jsonb;BEGIN
IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_ad03_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(n.nspacl) x WHERE n.nspname='primeline_ad03_backup' AND x.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(c.relacl) x WHERE n.nspname='primeline_ad03_backup' AND x.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_ad03_backup' AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'AD03_BACKUP_NOT_PRIVATE';END IF;
FOR r IN SELECT * FROM primeline_ad03_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg((to_jsonb(x)-''jornada_versao_id'') ORDER BY (to_jsonb(x)-''jornada_versao_id'')::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'AD03_DATA_DRIFT: %',r.tabela;END IF;END LOOP;END $data$;
SELECT 'AD03_POSTCHECK_OK' resultado;COMMIT;
